#pragma once
#include <map>
#include <string>
#include <string_view>

class Catalog {
public:
    bool add(int id, std::string name);
    bool contains(int id);
    std::string_view label(int id) const;
private:
    std::map<int, std::string> items_;
};

files.before:
#include "catalog.hpp"
#include <stdexcept>
#include <utility>

bool Catalog::add(int id, std::string name) {
    return items_.emplace(id, std::move(name)).second;
}

bool Catalog::contains(int id) {
    return items_.find(id) != items_.end();
}

std::string Catalog::label(int id) const {
    const auto found = items_.find(id);
    if (found == items_.end()) throw std::out_of_range("unknown product");
    std::string formatted = "Product: " + found->second;
    return formatted;
}

