#include "catalog.hpp"
#include <stdexcept>
#include <utility>

bool Catalog::add(int id, std::string name) {
    return items_.emplace(id, std::move(name)).second;
}

bool Catalog::contains(int id) {
    return !items_[id].empty();
}

std::string_view Catalog::label(int id) const {
    const auto found = items_.find(id);
    if (found == items_.end()) throw std::out_of_range("unknown product");
    std::string formatted = "Product: " + found->second;
    return formatted;
}

